# 数据文件：src/components/grove/Grove.tsx
# slug = src_components_grove_Grove_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是「Grove」条款更新的三处界面：一个是启动时弹出的条款确认弹窗（分宽限期与宽限期后两种文案），一个是设置里的隐私开关行。文件名 Grove 在界面上完全不出现，它对应的是「允许用你的对话与编码会话训练模型」这一项设置。三个组件共用同一批接口函数，区别只在呈现厚度：弹窗要解释改了什么、宽限期可以延后、开关行只有一行状态。'''),
    (10, 'before', '''五种退出决定构成一个完整的状态封闭集：同意并开启、同意但关闭、延后（仅宽限期可用）、直接退出（不可延后的场景）、不渲染（本就不该显示）。上层拿到这个值就知道该做什么，不需要再理解界面内部。'''),
    (16, 'before', '''手绘的一只 ASCII 纸箱，用来在弹窗右侧当插图。用模板字符串保留换行与反斜杠转义，是因为终端里没有图片可放，纯文本插图是唯一的视觉手段。这类常量通常由设计稿转写而来，改字体或改宽度都可能让箱子变形，属于「看着无用但删了界面会变丑」的一类代码。'''),
    (27, 'before', '''宽限期文案体：逐块渲染「条款何时生效、有哪些变化、去哪里看全文」。因为每个文本块都要被编译器的记忆化逐个缓存，所以整段读起来像一堆重复的「如果缓存槽是哨兵就构造一次」，真正的信息在那些被构造的节点里。'''),
    (31, 'before', '''第一段文案里的日期是硬编码的。这类日期一旦过期就会变成错误信息，所以真实项目里通常会改成配置项；这里保留硬编码说明它是随构建一起发布的一次性文案。注意句子中间插入了一个加粗的日期节点——这是终端富文本里表达强调的唯一方式。'''),
    (63, 'before', '''这一行是宽限期文案的主干：先拼出一对「圆点加粗标题」，再套一层缩进盒，最后把「这是什么变化」与「数据保留期变化」两段装进纵向容器。读这种嵌套结构时建议从最外层的属性往里看——外层决定间距与方向，内层才是文案本身。'''),
    (91, 'before', '''宽限期后的文案体，与上面同构但内容不同：去掉了「今天就可以接受」的语气、去掉了延后选项、并把数据保留期的说明改写成「开启则延长到五年、关闭则保持三十天」。两个组件没有抽公共壳，是因为文案结构差异大于重复成本——这种判断在界面代码里很常见，不要一看到相似就急着合并。'''),
    (144, 'before', '''弹窗本体。状态只有两个：是否该显示（三态——未知、要显示、不显示）、以及服务端下发的配置（可能为空）。三态设计让「还在拉配置」与「拉完了但不该显示」能区分开，前者返回空、后者也返回空，但语义不同，未来若要在加载期显示骨架屏就靠这个区分。'''),
    (151, 'before', '''两个状态都用空值初始化。配置单独存一份而不是塞进显示状态，是因为配置还要参与文案选择与选项生成（是否宽限期、是否域名被排除），生命周期比一次判断更长。'''),
    (158, 'before', '''并联拉两份数据：用户自己的设置、以及服务端的公告配置。用并联而不是串行，是因为两者互不依赖；任何一份失败都不会让另一份白等。'''),
    (161, 'before', '''是否显示交给一个纯函数判断，输入是三样：设置结果、配置结果、以及调用方给的「已经看过也照样显示」开关。把这个判断抽出去的好处是它可以被单独测试，而不必渲染整个弹窗。'''),
    (163, 'before', '''不该显示时立即回调「不渲染」并返回——注意是先回调再返回，而不是仅仅不渲染。上层需要这个回执才能继续启动流程，静默不渲染会让启动卡在这里。'''),
    (186, 'before', '''两个提前返回合起来就是「加载中」与「不该显示」两种情形，都渲染空。这里没有加载指示器，是因为这段判断发生在启动早期，任何多余的界面元素都会闪一下。'''),
    (194, 'before', '''选中处理：一个带标签的 switch，四个分支分别对应四种用户动作。带标签的意义在于每个分支都用同一个标签跳出——如果不加标签，某个分支里的跳出只会跳出 switch 而不是整个流程，最后那次「通知上层」就可能被跳过。这是这类多分支回调里最容易埋 bug 的写法。'''),
    (195, 'before', '''带标签的 switch：四个分支各自落盘设置或打点，然后统一跳出到标签处执行最后一句回调。读的时候要注意「哪些分支会写服务端」——只有两个同意分支会写，延后与退出都只打点，因为延后不代表表态。'''),
    (214, 'before', '''延后分支只打点不写设置：这正体现宽限期的语义——用户还没决定，下次启动再问。注意打点里带的状态是「真」，那是「曾经看过并延后」的语义，而不是「已开启」。'''),
    (221, 'before', '''退出分支没有跳出语句，因为它是最后一个分支；它同样只打点。落盘与打点的分离让「用户按了退出」与「用户明确拒绝」在数据里可以分辨，这对评估宽限期策略是否有效很关键。'''),
    (236, 'before', '''接受选项按「域名是否被排除」分两种：被排除时只给一个选项（且文案里说明了为什么只有关闭可选），未排除时给开启与关闭两个选项。这是产品规则直接映射到界面元素数量的典型例子——选项的存在与否本身就是一种说明。'''),
    (254, 'before', '''取消处理要按是否宽限期分派：宽限期里按退出等于延后（因为还能再问），宽限期外按退出等于放弃（不再问）。同一个按键在两种阶段语义不同，这是本文件第二个「同一交互两套语义」的地方。'''),
    (270, 'before', '''正文体按是否宽限期切换，外层是一个可增长的盒子。用可增长是为了让正文把剩余高度吃掉，把下面的选项区推到底部。'''),
    (300, 'before', '''「暂不」选项只在宽限期出现，非宽限期给一个空数组。这里没有用条件渲染，而是让选项数组本身变长变短——下游统一按数组处理，避免多一种分支。'''),
    (328, 'before', '''选项区：一行说明加一行「你的选择确认后立即生效」，再挂下拉框。说明文案里那句「立即生效」很重要，因为下面两个同意选项都会立刻写服务端，不存在二次确认。'''),
    (338, 'before', '''弹窗组装：标题与配色走主题里的强调色，取消回调与输入提示一起传入。注意这里的输入提示是作为函数传入的，收到退出状态后决定显示「再按一次退出」还是快捷键说明。'''),
    (349, 'before', '''输入提示函数：处于待确认退出状态时只显示一句警告，否则显示回车与退出的快捷键提示。这种「先提示再确认」的两段式退出，是为了防止误触把还没表态的用户直接踢出流程。'''),
    (357, 'before', '''设置里的隐私开关行。它比弹窗简单得多：一个本地开关状态、一个键处理、一行「标题、值」的布局。它不负责解释条款，只负责让用户随时改变主意。'''),
    (374, 'before', '''键处理：域名被排除时整行不可操作，所以第一层守卫就是排除它。其余情况把制表键、回车键、空格三个都当作切换——设置列表里用户可能用任意一种「确认」习惯，全部接受比强制某一种更友好。切换后立即写服务端，本地状态只是镜像。'''),
    (397, 'before', '''值的显示分三种优先级：域名被排除时显示带红字的假值（并注明原因），否则开启显示绿字真、关闭显示红字假。注意关闭时用的是默认初始值那个红色假节点，也就是说关闭状态直接复用首个缓存槽的节点——这是编译器优化留下的结构，读的时候别误以为关闭没有单独分支。'''),
    (460, 'before', '''挂载时打一次点，记录「用户看到了隐私设置页」。用空依赖数组保证只打一次；打点内容为空对象，因为这里只关心次数不关心维度。'''),
]
